package es.aelb.backendweb.infrastructure.email;
import es.aelb.backendweb.infrastructure.config.EmailProperties; import jakarta.annotation.PostConstruct; import org.springframework.stereotype.Component;
@Component public class EmailConfigurationValidator { private final EmailProperties p; public EmailConfigurationValidator(EmailProperties p){this.p=p;} @PostConstruct void validate(){if(p.getMaxPerSecond()<1||p.getBatchSize()<1||p.getMaxRetries()<1||p.getWorkerConcurrency()<1)throw new IllegalStateException("Configuración de email inválida");if("prod".equalsIgnoreCase(p.getAppEnv())){if(!"ses".equalsIgnoreCase(p.getProvider())||p.getFrom().isBlank()||p.getAwsRegion().isBlank()||p.getTokenEncryptionKey().isBlank()||p.getTokenEncryptionKey().contains("local-only"))throw new IllegalStateException("Configuración SES incompleta o insegura en producción");}else if(!"smtp".equalsIgnoreCase(p.getProvider()))throw new IllegalStateException("SES solo puede habilitarse explícitamente en producción");}}
